{
  "allow_create": false,
  "rigorous_codebase": true,
  "test_cmds": [
    {
      "cmd": "scripts/train_moe.sh",
      "label": "R4",
      "group": 1,
      "compute": 1.0,
      "time": "05:00:00",
      "package": "nanoGPT"
    },
    {
      "cmd": "scripts/train_moe.sh",
      "label": "R16",
      "group": 1,
      "compute": 1.0,
      "time": "05:00:00",
      "package": "nanoGPT"
    },
    {
      "cmd": "scripts/train_moe.sh",
      "label": "R64",
      "group": 1,
      "compute": 1.0,
      "time": "05:00:00",
      "package": "nanoGPT"
    }
  ],
  "baselines": {
    "null": {
      "edit_ops": "edits/null.edit.py",
      "null": true
    },
    "dropout": {
      "edit_ops": "edits/dropout.edit.py"
    },
    "load_balance": {
      "edit_ops": "edits/load_balance.edit.py"
    },
    "masking": {
      "edit_ops": "edits/masking.edit.py"
    }
  },
  "files": [
    {
      "filename": "nanoGPT/custom_pretrain.py",
      "read": [
        {
          "start": -1,
          "end": -1
        }
      ],
      "edit": [
        {
          "start": 141,
          "end": 203
        }
      ]
    }
  ],
  "seeds": [
    42,
    43,
    44
  ],
  "data_deps": [
    {
      "name": "fineweb10b",
      "description": "FineWeb-10B in GPT-2 BPE (kjj0/fineweb10B-gpt2 @ 889765ea, the modded-nanogpt pretokenisation of FineWeb sample-10BT): train.bin = the 103 train shards (10,255,324,043 tokens), val.bin = the held-out validation shard (100,000,000 tokens), headerless uint16 (~20.7GB). Every shard is checked against its pinned sha256.",
      "host_path": "{data_root}/fineweb10b",
      "container_path": "/data/fineweb10b",
      "ready_files": [
        "{data_root}/fineweb10b/train.bin",
        "{data_root}/fineweb10b/val.bin"
      ],
      "prepare": "vendor/data_scripts/nanoGPT/prepare_fineweb10b.py"
    },
    {
      "name": "moe-repeat-fineweb",
      "host_path": "{data_root}/moe-repeat-fineweb",
      "container_path": "/data/moe-repeat-fineweb",
      "ready_files": [
        "{data_root}/moe-repeat-fineweb/train_R4.bin",
        "{data_root}/moe-repeat-fineweb/train_R16.bin",
        "{data_root}/moe-repeat-fineweb/train_R64.bin",
        "{data_root}/moe-repeat-fineweb/val.bin",
        "{data_root}/moe-repeat-fineweb/wikitext2.bin",
        "{data_root}/moe-repeat-fineweb/lambada.bin"
      ],
      "prepare": "vendor/data_scripts/nanoGPT/prepare_moe_repeat.py",
      "prepare_args": [
        "--no-r1"
      ],
      "description": "FineWeb-10B repetition slices: U-token train bins for R=4/16/64, nested prefixes of one seeded document-level permutation of the FineWeb-10B train split, + FineWeb's held-out validation shard + OOD PPL eval bins (WikiText-2, LAMBADA). Only these are shipped; the 10.26B-token FineWeb train split and the all-unique R=1 reference bin are NOT shipped."
    }
  ],
  "data_deps_include": [
    "fineweb10b",
    "eval",
    "moe-repeat-fineweb"
  ],
  "_data_deps_include_note": "prepare_moe_repeat.py cuts the repetition bins out of {data_root}/fineweb10b/train.bin and copies the OOD eval bins from {data_root}/eval, so both must be PREPARED at build time (fineweb10b is declared before moe-repeat-fineweb, so the data stage builds it first). They are build inputs only -- `harbor_strip_paths` below removes the full FineWeb training split from the finished image, because an in-process regulariser that could np.memmap it would draw fresh unique tokens and defeat the repetition constraint the whole task measures. prepare_fineweb10b.py leaves no shard cache behind, and the build-time R=1 reference dir is stripped too.",
  "harbor_strip_paths": [
    "/data/fineweb10b",
    "/data/moe-repeat-fineweb-ref"
  ],
  "harbor_resources": {
    "budget_check_timeout_sec": 1200,
    "storage_mb": 30720
  }
}
